css:
.loopsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2937;
    background:
        radial-gradient(circle at 88% -4%, rgba(124, 58, 237, 0.10) 0%, rgba(124, 58, 237, 0) 42%),
        radial-gradient(circle at 4% 0%, rgba(6, 182, 212, 0.12) 0%, rgba(6, 182, 212, 0) 40%),
        #f4f7fb;
    border-radius: 18px;
}

.loopsim-container * {
    box-sizing: border-box;
}

.loopsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0b1530 0%, #16234d 52%, #0f3b46 100%);
    color: #eaf4ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1d2c52;
    box-shadow: 0 14px 36px rgba(11, 21, 48, 0.30);
}

.loopsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.loopsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #5ee0d0;
    background: rgba(94, 224, 208, 0.12);
    border: 1px solid rgba(94, 224, 208, 0.32);
    padding: 5px 14px;
    border-radius: 999px;
}

.loopsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #bcd0ea;
}

.loopsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #51607a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.loopsim-period-counter #currentDay,
.loopsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0e7490;
}

.loopsim-round-name {
    background: rgba(14, 116, 144, 0.12);
    color: #0e7490;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.loopsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b45309;
    background: rgba(245, 158, 11, 0.14);
    border: 1px solid rgba(245, 158, 11, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.loopsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.loopsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2e8f2;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.06);
    border-top: 4px solid #94a3b8;
}

.loopsim-card-seek { border-top-color: #06b6d4; }
.loopsim-card-trust { border-top-color: #7c3aed; }
.loopsim-card-adapt { border-top-color: #0e9f6e; }
.loopsim-card-risk { border-top-color: #f97316; }

.loopsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #64748b;
}

.loopsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0f172a;
    font-variant-numeric: tabular-nums;
}

.loopsim-card-seek .loopsim-value { color: #0891b2; }
.loopsim-card-trust .loopsim-value { color: #7c3aed; }
.loopsim-card-adapt .loopsim-value { color: #059669; }
.loopsim-card-risk .loopsim-value { color: #ea580c; }

.loopsim-sublabel {
    font-size: 0.76rem;
    color: #7a8aa0;
    line-height: 1.35;
}

.loopsim-trust-high { border-top-color: #16a34a; }
.loopsim-trust-high .loopsim-value { color: #16a34a; }
.loopsim-trust-low { border-top-color: #dc2626; }
.loopsim-trust-low .loopsim-value { color: #dc2626; }

.loopsim-risk-high { border-top-color: #dc2626; }
.loopsim-risk-high .loopsim-value { color: #dc2626; }
.loopsim-risk-low { border-top-color: #16a34a; }
.loopsim-risk-low .loopsim-value { color: #16a34a; }

.loopsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: linear-gradient(100deg, #ecfeff 0%, #f5f3ff 100%);
    border: 1px solid #cbe9f0;
    color: #334155;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.loopsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #0e7490;
}

.loopsim-budget-over #budgetDisplay {
    color: #dc2626;
}

.loopsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #06b6d4;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #e2e8f2;
    border-left-width: 5px;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
}

.loopsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.loopsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f172a;
    margin-bottom: 6px;
}

.loopsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #334155;
}

.loopsim-briefing-text strong { color: #0e7490; }
.loopsim-briefing-text em { color: #b45309; font-style: italic; }

.loopsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2e8f2;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
}

.loopsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f172a;
    border-bottom: 2px solid #eef2f8;
    padding-bottom: 8px;
}

.loopsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #1e293b;
    margin: 14px 0 6px;
}

.loopsim-container select,
.loopsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbd5e1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8fafc;
    color: #0f172a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.loopsim-container select:focus,
.loopsim-container input[type="number"]:focus {
    outline: none;
    border-color: #06b6d4;
    box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.18);
}

.loopsim-container select option {
    background-color: #ffffff;
    color: #0f172a;
}

.loopsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7c3aed;
}

.loopsim-range-readout,
.loopsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #51607a;
    margin-top: 4px;
}

.loopsim-range-readout span:nth-child(2),
.loopsim-alloc-readout span:nth-child(2) {
    color: #7c3aed;
    font-weight: 800;
}

.loopsim-hint {
    font-size: 0.8rem;
    color: #7a8aa0;
    margin-top: 4px;
    line-height: 1.4;
}

.loopsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.loopsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f8fafc;
    border: 1px solid #e3e9f2;
    border-radius: 9px;
    padding: 8px 12px;
}

.loopsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #334155;
}

.loopsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
    background-color: #ffffff;
}

.loopsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.loopsim-container .btn-primary {
    background: linear-gradient(135deg, #0891b2 0%, #06b6d4 50%, #7c3aed 130%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(8, 145, 178, 0.32);
}

.loopsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.loopsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbd5e1;
    color: #51607a;
    background: transparent;
}

.loopsim-coach {
    background: linear-gradient(135deg, #0b1530 0%, #142244 60%, #103040 100%);
    color: #dbe8f6;
    border: 1px solid #1d2c52;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(11, 21, 48, 0.22);
}

.loopsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #5ee0d0;
    margin-bottom: 8px;
}

.loopsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.loopsim-coach-body strong { color: #5ee0d0; }
.loopsim-coach-body em { color: #fbbf24; font-style: italic; }

.loopsim-history,
.loopsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2e8f2;
    box-shadow: 0 6px 18px rgba(15, 23, 42, 0.05);
}

.loopsim-history h3,
.loopsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f172a;
}

.loopsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #334155;
}

.loopsim-container table#usfHistoryTable th {
    background: #f1f5fb;
    color: #0e7490;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d9e2ee;
}

.loopsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
    color: #334155;
}

.loopsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafc;
}

.loopsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .loopsim-container {
        padding: 14px;
    }
    .loopsim-header h1 {
        font-size: 1.7rem;
    }
    .loopsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .loopsim-value {
        font-size: 2rem;
    }
    .loopsim-clock {
        margin-left: 0;
    }
    .loopsim-period-counter {
        font-size: 0.88rem;
    }
    .loopsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .loopsim-alloc-row {
        flex-wrap: wrap;
    }
    .loopsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .loopsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (loopsim) ---- */
.loopsim-completion { padding: 8px 4px 4px; }
.loopsim-cm-head { text-align: center; margin-bottom: 16px; }
.loopsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4f6b8a; }
.loopsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8ba0b8; }
.loopsim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #232d38; }
.loopsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.loopsim-cm-yes { background: rgba(79,107,138,0.16); color: #4f6b8a; border: 1px solid rgba(79,107,138,0.5); }
.loopsim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.loopsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.loopsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(79,107,138,0.08); border: 1px solid rgba(79,107,138,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.loopsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #4f6b8a; }
.loopsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.loopsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #232d38; }
.loopsim-cm-insights { margin: 0; padding-left: 20px; }
.loopsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

