(function() {
    'use strict';

    class LearningLoopAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Learning Loop`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Atlas squad @ Lumera Cloud Pty Ltd).
            this.SEEK_BASELINE = 14;        // pre-PulseHR feedback-seeking events / engineer / quarter
            this.HOUR_BUDGET = 6;           // hard cap: 6 engineer-hours / person / week for learning activity
            this.SERVICE_CREDIT = 540000;   // AUD service-credit clause on a 4th miss
            this.REPLACE_COST = 180000;     // AUD to replace a flight-risk senior engineer
            this.PULSEHR_SUNK = 1.1;        // AUD 1.1M sunk cost — board will not switch it off

            // Concept truths (the modelled-correct path).
            this.TRUE_ROOT = `imagecost`;
            this.TRUE_BOUNDARY = `devonly`;
            this.TRUE_SCALE = `pilot`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    seek: 3,                 // feedback-seeking events / engineer / quarter (now 3, baseline 14)
                    trust: 34,               // "I trust how my performance is evaluated" (0-100)
                    adapt: 38,               // adaptive performance index (0-100); rework 22%, cycle-time variance 2x
                    risk: 70,                // delivery / service-credit exposure (0-100, lower better)
                    hoursUsed: 0,            // weekly learning-time committed this design (of 6h)
                    loopClosed: false,
                    devEvalSplit: false,
                    overPromised: false,     // scaled by fiat / no stop condition
                    seekHistory: [3],
                    trustHistory: [34],
                    adaptHistory: [38],
                    riskHistory: [70],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC ERRORS so a blind click-through cannot auto-win.
                state.decisions = {
                    root: `lazy`,
                    split: `same`,
                    conf: 50,
                    peer: 1.5,
                    retro: 1.0,
                    aar: 1.0,
                    upward: 0.5,
                    customer: 0.5,
                    loop: `none`,
                    signals: `keepall`,
                    scope: `individual`,
                    boundary: `both`,
                    trans: 40,
                    lead: `velocity`,
                    stop: `none`,
                    scale: `fiat`,
                    pitch: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rt = document.getElementById(`rootInput`);
                const sp = document.getElementById(`splitInput`);
                const cf = document.getElementById(`confInput`);
                if (rt) decisions.root = rt.value;
                if (sp) decisions.split = sp.value;
                if (cf) decisions.conf = parseInt(cf.value, 10);
                if (!Number.isFinite(decisions.conf) || decisions.conf < 0 || decisions.conf > 100) {
                    warn(`warn_conf_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`peerInput`, `retroInput`, `aarInput`, `upwardInput`, `customerInput`];
                const keys = [`peer`, `retro`, `aar`, `upward`, `customer`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const lp = document.getElementById(`loopInput`);
                if (lp) decisions.loop = lp.value;
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_hours_negative`); return false;
                }
                const total = Math.round((parts.reduce((a, b) => a + b, 0)) * 10) / 10;
                if (total > this.HOUR_BUDGET + 0.001) {
                    warn(`warn_hours_over`); return false;
                }
                if (total <= 0) {
                    warn(`warn_hours_zero`); return false;
                }
            } else if (round === 3) {
                const sg = document.getElementById(`signalsInput`);
                const sc = document.getElementById(`scopeInput`);
                const bd = document.getElementById(`boundaryInput`);
                const tr = document.getElementById(`transInput`);
                if (sg) decisions.signals = sg.value;
                if (sc) decisions.scope = sc.value;
                if (bd) decisions.boundary = bd.value;
                if (tr) decisions.trans = parseInt(tr.value, 10);
                if (!Number.isFinite(decisions.trans) || decisions.trans < 0 || decisions.trans > 100) {
                    warn(`warn_trans_range`); return false;
                }
            } else if (round === 4) {
                const ld = document.getElementById(`leadInput`);
                const st = document.getElementById(`stopInput`);
                const sl = document.getElementById(`scaleInput`);
                const pt = document.getElementById(`pitchInput`);
                if (ld) decisions.lead = ld.value;
                if (st) decisions.stop = st.value;
                if (sl) decisions.scale = sl.value;
                if (pt) decisions.pitch = parseInt(pt.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let seekDelta = 0, trustDelta = 0, adaptDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the learning system: separate environment from measurement; name the image cost.
                switch (d.root) {
                    case `imagecost`: trustDelta += 8; adaptDelta += 4; riskDelta -= 5; coachKey = `coach_r1_imagecost`; break;
                    case `channels`: trustDelta -= 2; riskDelta += 4; coachKey = `coach_r1_channels`; break;
                    case `metrics`: trustDelta += 1; adaptDelta += 1; coachKey = `coach_r1_metrics`; break;
                    case `lazy`: trustDelta -= 6; adaptDelta -= 3; riskDelta += 8; coachKey = `coach_r1_lazy`; break;
                }

                switch (d.split) {
                    case `both`: trustDelta += 6; adaptDelta += 3; riskDelta -= 4; if (d.root === `imagecost`) coachKey = `coach_r1_sharp`; break;
                    case `measure`: adaptDelta += 1; riskDelta += 2; break;
                    case `environment`: trustDelta -= 2; riskDelta += 3; break;
                    case `same`: trustDelta -= 4; riskDelta += 4; coachKey = `coach_r1_same`; break;
                }

                // Calibrated confidence: enough conviction to act, not over-confident on a shallow read.
                const shallow = (d.root !== `imagecost` || d.split !== `both`);
                if (d.conf >= 60 && !shallow) { adaptDelta += 3; riskDelta -= 3; }
                else if (d.conf >= 70 && shallow) { trustDelta -= 3; riskDelta += 4; coachKey = `coach_r1_overconfident`; }
                else if (d.conf <= 25) { adaptDelta -= 2; riskDelta += 3; coachKey = `coach_r1_stalled`; }

                summaryKey = (d.root === `imagecost` && d.split === `both`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design feedback channels + reflection routines inside the 6-hour budget.
                const hours = Math.round((d.peer + d.retro + d.aar + d.upward + d.customer) * 10) / 10;
                ds.hoursUsed = hours;
                const channelCount = [d.peer, d.retro, d.aar, d.upward, d.customer].filter((h) => h > 0).length;

                // Each productive channel lifts feedback-seeking — but more channels alone is not culture.
                seekDelta += Math.min(7, d.peer * 2 + d.retro * 1.2 + d.aar * 1.5 + d.upward * 1.0 + d.customer * 0.6);
                adaptDelta += d.retro * 2 + d.aar * 2 + d.peer * 1;

                // Common Error 1: confusing volume with culture — many channels, no closed loop.
                if (channelCount >= 4 && d.loop !== `close`) {
                    trustDelta -= 4; riskDelta += 4; coachKey = `coach_r2_volume`;
                }

                // Reflection must close the loop (Common Error 4: a journal, not a learning loop).
                switch (d.loop) {
                    case `close`:
                        ds.loopClosed = true;
                        adaptDelta += 8; trustDelta += 4; riskDelta -= 6;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_close`;
                        break;
                    case `report`:
                        adaptDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r2_report` : coachKey;
                        break;
                    case `none`:
                        adaptDelta -= 3; trustDelta -= 2;
                        coachKey = (coachKey === `coach_default`) ? `coach_r2_journal` : coachKey;
                        break;
                }

                // Tight, focused budget use is rewarded; near-overload (5.5h+) signals process drowning delivery.
                if (hours <= this.HOUR_BUDGET && hours >= 3.5 && hours <= 5.5) { adaptDelta += 2; }
                else if (hours > 5.5) { riskDelta += 3; adaptDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r2_overload` : coachKey; }
                else if (hours < 2.5) { adaptDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_thin` : coachKey; }

                summaryKey = (d.loop === `close` && hours <= this.HOUR_BUDGET && hours >= 3) ? `sum_r2_good` :
                             (d.loop === `none` ? `sum_r2_journal` : `sum_r2_weak`);
            } else if (round === 3) {
                // Re-tune PulseHR under the trust constraint (board won't switch it off).
                switch (d.signals) {
                    case `tune`: trustDelta += 8; adaptDelta += 5; seekDelta += 2; riskDelta -= 3; coachKey = `coach_r3_tune`; break;
                    case `keepall`: trustDelta -= 5; adaptDelta -= 3; riskDelta += 4; coachKey = `coach_r3_keepall`; break;
                    case `addmore`: trustDelta -= 7; seekDelta -= 1; riskDelta += 5; coachKey = `coach_r3_addmore`; break;
                    case `detonate`: trustDelta += 2; adaptDelta -= 2; riskDelta += 7; coachKey = `coach_r3_detonate`; break;
                }

                // Individual vs squad-level scoring — squad-level de-zeroes the gaming.
                if (d.scope === `squad`) { trustDelta += 4; adaptDelta += 3; }
                else { riskDelta += 1; }

                // Developmental vs evaluative boundary — THE lever that broke Atlas.
                switch (d.boundary) {
                    case `devonly`:
                        ds.devEvalSplit = true;
                        trustDelta += 12; seekDelta += 4; adaptDelta += 3; riskDelta -= 5;
                        if (d.signals === `tune`) coachKey = `coach_r3_split`;
                        break;
                    case `payonly`:
                        trustDelta -= 4; seekDelta -= 2; riskDelta += 3; coachKey = (coachKey === `coach_r3_tune`) ? `coach_r3_payonly` : coachKey;
                        break;
                    case `both`:
                        trustDelta -= 8; seekDelta -= 3; riskDelta += 5; coachKey = `coach_r3_both`;
                        break;
                }

                // Transparency & appeal rebuild trust into the data.
                if (d.trans >= 70) { trustDelta += 6; seekDelta += 2; }
                else if (d.trans >= 40) { trustDelta += 2; }
                else { trustDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_opaque` : coachKey; }

                summaryKey = (d.signals === `tune` && d.boundary === `devonly`) ? `sum_r3_good` :
                             (d.boundary === `both` ? `sum_r3_blurred` :
                             (d.signals === `detonate` ? `sum_r3_detonate` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover & institutionalise: leading/lagging dashboard, stop condition, pilot-not-fiat.
                switch (d.lead) {
                    case `leading`: trustDelta += 5; adaptDelta += 4; riskDelta -= 6; coachKey = `coach_r4_leading`; break;
                    case `ontime`: riskDelta += 3; coachKey = `coach_r4_ontime`; break;
                    case `velocity`: trustDelta -= 3; riskDelta += 4; coachKey = `coach_r4_velocity`; break;
                }

                switch (d.stop) {
                    case `trust`: trustDelta += 4; adaptDelta += 3; riskDelta -= 5; break;
                    case `delivery`: riskDelta += 3; break;
                    case `none`: ds.overPromised = true; riskDelta += 5; adaptDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_nostop` : coachKey; break;
                }

                switch (d.scale) {
                    case `pilot`: trustDelta += 6; adaptDelta += 4; riskDelta -= 6; if (d.lead === `leading`) coachKey = `coach_r4_pilot`; break;
                    case `freeze`: adaptDelta += 1; riskDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r4_freeze` : coachKey; break;
                    case `fiat`: ds.overPromised = true; trustDelta -= 8; riskDelta += 7; adaptDelta -= 2; coachKey = `coach_r4_fiat`; break;
                }

                if (d.pitch >= 60) { trustDelta += 3; riskDelta -= 2; }
                else if (d.pitch <= 25) { riskDelta += 3; }

                summaryKey = (d.lead === `leading` && d.stop === `trust` && d.scale === `pilot`) ? `sum_r4_good` :
                             (d.scale === `fiat` ? `sum_r4_fiat` : `sum_r4_weak`);
            }

            // Feedback-seeking only truly recovers when trust is being rebuilt — gate the seek gains on trust.
            if (round >= 2 && !ds.devEvalSplit && round >= 3) {
                seekDelta = Math.min(seekDelta, 1); // can't restore candour while one score still sets pay
            }

            // Apply deltas. seek 0-14 scale, trust/adapt 0-100, risk 0-100 (lower better).
            ds.seek = Math.max(0, Math.min(this.SEEK_BASELINE, Math.round((ds.seek + seekDelta) * 10) / 10));
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));
            ds.adapt = Math.max(0, Math.min(100, Math.round(ds.adapt + adaptDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            ds.seekHistory.push(ds.seek);
            ds.trustHistory.push(ds.trust);
            ds.adaptHistory.push(ds.adapt);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                seek: ds.seek,
                seekDelta: Math.round(seekDelta * 10) / 10,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                adapt: ds.adapt,
                adaptDelta: Math.round(adaptDelta),
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                hoursUsed: ds.hoursUsed,
                loopClosed: ds.loopClosed,
                devEvalSplit: ds.devEvalSplit,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Australia / AUD — single consistent symbol "A$", thousands grouped, no decimals.
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Math.round(v));
            return `${sign}A$${abs.toLocaleString(`en-AU`)}`;
        }

        _fmtSeek(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            return (lang === `es`) ? String(n).replace(`.`, `,`) : String(n);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

