            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.loopsim-card-trust`);
                if (card) {
                    card.classList.toggle(`loopsim-trust-high`, Number(v) >= 65);
                    card.classList.toggle(`loopsim-trust-low`, Number(v) <= 35);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`adaptDisplay`, `domainState.adapt`, (v) => Math.round(Number(v)));
            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const card = document.querySelector(`.loopsim-card-risk`);
                if (card) {
                    card.classList.toggle(`loopsim-risk-high`, Number(v) >= 60);
                    card.classList.toggle(`loopsim-risk-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.hoursUsed`, (v) => {
                const bar = document.querySelector(`.loopsim-budget-bar`);
                if (bar) bar.classList.toggle(`loopsim-budget-over`, Number(v) > self.HOUR_BUDGET + 0.001);
                return `${self._fmtSeek(v)} / ${self._fmtSeek(self.HOUR_BUDGET)} h`;
            });

            // Confidence slider readout (R1).
            const cf = document.getElementById(`confInput`);
            const cfReadout = document.getElementById(`confReadout`);
            if (cf && cfReadout) {
                cfReadout.textContent = cf.value;
                cf.addEventListener(`input`, function() { cfReadout.textContent = cf.value; });
            }

            // Transparency slider readout (R3).
            const tr = document.getElementById(`transInput`);
            const trReadout = document.getElementById(`transReadout`);
            if (tr && trReadout) {
                trReadout.textContent = tr.value;
                tr.addEventListener(`input`, function() { trReadout.textContent = tr.value; });
            }

            // Live weekly-hours total (R2) — must stay within 6h.
            const allocIds = [`peerInput`, `retroInput`, `aarInput`, `upwardInput`, `customerInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = self._fmtSeek(total);
                const bar = document.querySelector(`.loopsim-alloc-readout`);
                if (bar) bar.style.color = (total > self.HOUR_BUDGET + 0.001) ? `#dc2626` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

