        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                loopChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.adaptHistory },
                        { data: ds.riskHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const seek = Math.round(ds.seek * 10) / 10;
            const trust = Math.round(ds.trust);
            const adapt = Math.round(ds.adapt);
            const risk = Math.round(ds.risk);
            const seekScore = Math.max(0, Math.min(100, (seek / this.SEEK_BASELINE) * 100));
            return Math.max(0, Math.min(100, Math.round(trust * 0.30 + adapt * 0.28 + (100 - risk) * 0.27 + seekScore * 0.15)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const seek = Math.round(ds.seek * 10) / 10;
            const trust = Math.round(ds.trust);
            const adapt = Math.round(ds.adapt);
            const risk = Math.round(ds.risk);

            // Composite: trust, adaptive performance, low delivery risk, plus a feedback-seeking recovery bonus.
            const composite = this._composite(ds);

            const trusted = trust >= 60;
            const adaptive = adapt >= 60;
            const delivered = risk <= 35;
            const candid = seek >= 9;
            const gamedAgain = ds.overPromised || (!ds.devEvalSplit && trust < 50) || risk >= 65;

            let performance = window.mySimulation.t(`grade_broken`);
            if (trusted && adaptive && delivered && composite >= 75) performance = window.mySimulation.t(`grade_restored`);
            else if (trusted && (adaptive || delivered)) performance = window.mySimulation.t(`grade_underway`);
            else if (gamedAgain) performance = window.mySimulation.t(`grade_gamed`);
            else if (risk >= 70) performance = window.mySimulation.t(`grade_fourthmiss`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (trusted && adaptive && delivered) insights.push(window.mySimulation.t(`insight_restored`));
            else if (gamedAgain) insights.push(window.mySimulation.t(`insight_gamed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!ds.devEvalSplit) insights.push(window.mySimulation.t(`insight_noboundary`));
            if (!ds.loopClosed) insights.push(window.mySimulation.t(`insight_noloop`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_fiat`));
            if (candid) insights.push(window.mySimulation.t(`insight_candid`));
            if (risk >= 60) insights.push(window.mySimulation.t(`insight_credit`));

            return {
                seek: seek,
                trust: trust,
                adapt: adapt,
                risk: risk,
                trusted: trusted,
                adaptive: adaptive,
                delivered: delivered,
                candid: candid,
                gamedAgain: gamedAgain,
                met: (trusted && adaptive && delivered && composite >= 75),
                fourthMiss: (risk >= 70),
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="loopsim-cm-badge loopsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="loopsim-cm-badge loopsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.gamedAgain) failBadge += ` <span class="loopsim-cm-badge loopsim-cm-no">` + T(`cm_gamed`) + `</span>`;
            if (s.fourthMiss) failBadge += ` <span class="loopsim-cm-badge loopsim-cm-no">` + T(`cm_fourthmiss`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="loopsim-cm-metric"><span class="loopsim-cm-mv">` + (Math.round((s.seek || 0) * 10) / 10) + `</span><span class="loopsim-cm-ml">` + T(`cm_m_seek`) + `</span></div>`
                + `<div class="loopsim-cm-metric"><span class="loopsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="loopsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="loopsim-cm-metric"><span class="loopsim-cm-mv">` + Math.round(s.adapt || 0) + `</span><span class="loopsim-cm-ml">` + T(`cm_m_adapt`) + `</span></div>`
                + `<div class="loopsim-cm-metric"><span class="loopsim-cm-mv">` + Math.round(s.risk || 0) + `</span><span class="loopsim-cm-ml">` + T(`cm_m_risk`) + `</span></div>`;
            return ``
                + `<div class="loopsim-completion">`
                +   `<div class="loopsim-cm-head">`
                +     `<div class="loopsim-cm-score">` + score + `<span class="loopsim-cm-score-max">/100</span></div>`
                +     `<div class="loopsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="loopsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="loopsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="loopsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (!ds.devEvalSplit && state.currentPeriod >= 3) return window.mySimulation.t(`hint_boundary`);
            if (!ds.loopClosed && state.currentPeriod >= 2) return window.mySimulation.t(`hint_loop`);
            if (ds.overPromised) return window.mySimulation.t(`hint_fiat`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.trust < 45 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_trust`);
            if (ds.trust >= 65 && ds.adapt >= 60 && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

